Given a positive integer n and the task is to print all the Super-Primes less than or equal to n. Super-prime numbers (also known as higher order primes) are the subsequence of prime number sequence that occupy prime-numbered positions within the sequence of all prime numbers. The first few super primes are 3, 5, 11, and 17. Examples: Input: n = 7Output: 3 5 Explanation: In list of primes (2, 3, 5, 7}, 3 and 5 are super primes because they appear at 2nd and 3rd positions which are also a prime . Input: n = 17Output: 3 5 11 17Explanation: In list of primes (2, 3, 5, 7, 11, 13, 17), 3, 5, 11 and 17 are super primes because they appear at 2nd, 3rd, 5th and 7th positions which are also a prime . Try It YourselfThe idea is to generate all the primes less than or equal to the given number n using the Sieve of Eratosthenes. Once we have generated all such primes, we iterate through the array and print all prime number that occupy prime number positions. 
            C++

    #include <bits/stdc++.h>
using namespace std;

// Generate all prime numbers less than n.
bool SieveOfEratosthenes(int n, bool isPrime[])
{
    // Initialize all entries of boolean array as true. A
    // value in isPrime[i] will finally be false if i is Not
    // a prime, else true bool isPrime[n+1];
    isPrime[0] = isPrime[1] = false;
    for (int i = 2; i <= n; i++)
        isPrime[i] = true;

    for (int p = 2; p * p <= n; p++) {

        // If isPrime[p] is not changed, then it is  a prime
        if (isPrime[p] == true) {

            // Update all multiples of p
            for (int i = p * 2; i <= n; i += p)
                isPrime[i] = false;
        }
    }
}

// Prints all super primes less than or equal to n.
vector<int> superPrimes(int n)
{
    // Generating primes using Sieve
    vector<int> ans ;
    bool isPrime[n + 1];
    SieveOfEratosthenes(n, isPrime);

    // Storing all the primes generated in a an array
    // primes[]
    int primes[n + 1], j = 0;
    for (int p = 2; p <= n; p++)
        if (isPrime[p])
            primes[j++] = p;

    // Printing all those prime numbers that occupy prime
    // numbered position in sequence of prime numbers.
    for (int k = 0; k < j; k++)
        if (isPrime[k + 1])
            ans.push_back(primes[k]);

    return ans; 
}


int main()
{
    int n = 241;
    vector<int> sPrimes = superPrimes(n);
    for( int i=0; i<sPrimes.size(); i++)
    {
        cout<<sPrimes[i]<<" "; 
    }
    return 0;
}


